; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpc (Amstrad CPC - direct hardware, no firmware), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 14: Print "1 started"
			dw kw_printzoscii
			dw glyph_31, glyph_20, glyph_73, glyph_74, glyph_61, glyph_72, glyph_74, glyph_65
			dw glyph_64, 1, 0		; "1 started\n"

			; main.bas 15: Wait
			dw p_wait_c

			; main.bas 16: Print "2 Capability LOAD"; FileSystem.Capability("LOAD"); " SAVE"; FileSystem.Capability("SAVE")
			dw fn_filesystem_capability, str0, var_filesystem_capability_capability
			dw kw_printzoscii
			dw glyph_32, glyph_20, glyph_43, glyph_61, glyph_70, glyph_61, glyph_62, glyph_69
			dw glyph_6C, glyph_69, glyph_74, glyph_79, glyph_20, glyph_4C, glyph_4F, glyph_41
			dw glyph_44, 0		; "2 Capability LOAD"
			dw kw_printint, var_filesystem_capability_capability
			dw fn_filesystem_capability, str1, var_filesystem_capability_capability
			dw kw_printzoscii
			dw glyph_20, glyph_53, glyph_41, glyph_56, glyph_45, 0		; " SAVE"
			dw kw_printint, var_filesystem_capability_capability
			dw kw_printnl

			; main.bas 17: Wait
			dw p_wait_c

			; main.bas 18: Print "3 Devices: "; FileSystem.Devices()
			dw p_filesystem_devices_c
			dw kw_printzoscii
			dw glyph_33, glyph_20, glyph_44, glyph_65, glyph_76, glyph_69, glyph_63, glyph_65
			dw glyph_73, glyph_3A, glyph_20, 0		; "3 Devices: "
			dw kw_printstrvar, var_filesystem_devices_devices
			dw kw_printnl

			; main.bas 19: Wait
			dw p_wait_c

			; main.bas 20: Print "4 CurrentDevice: "; FileSystem.CurrentDevice(); "  Volume: "; FileSystem.CurrentVolume()
			dw p_filesystem_currentdevice_c
			dw kw_printzoscii
			dw glyph_34, glyph_20, glyph_43, glyph_75, glyph_72, glyph_72, glyph_65, glyph_6E
			dw glyph_74, glyph_44, glyph_65, glyph_76, glyph_69, glyph_63, glyph_65, glyph_3A
			dw glyph_20, 0		; "4 CurrentDevice: "
			dw kw_printstrvar, var_filesystem_currentdevice_currentdevice
			dw p_filesystem_currentvolume_c
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_56, glyph_6F, glyph_6C, glyph_75, glyph_6D, glyph_65
			dw glyph_3A, glyph_20, 0		; "  Volume: "
			dw kw_printstrvar, var_filesystem_currentvolume_currentvolume
			dw kw_printnl

			; main.bas 21: Wait
			dw p_wait_c

			; main.bas 22: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dw kw_ztov, var_i
for1_t:
			dw kw_mulvl, var_i, 50, tmp2
			dw kw_sublv, 1000, tmp2, tmp1
			dw kw_aset, arr_a, var_i, tmp1
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; main.bas 23: Print "5 Save STEP.DAT..."
			dw kw_printzoscii
			dw glyph_35, glyph_20, glyph_53, glyph_61, glyph_76, glyph_65, glyph_20, glyph_53
			dw glyph_54, glyph_45, glyph_50, glyph_2E, glyph_44, glyph_41, glyph_54, glyph_2E
			dw glyph_2E, glyph_2E, 1, 0		; "5 Save STEP.DAT...\n"

			; main.bas 24: Wait
			dw p_wait_c

			; main.bas 25: r = FileSystem.Save("STEP.DAT", VarPtr(a), 20)
			dw p_filesystem_save_c, str2, vp_arr_a, lit_20
			dw kw_vtov, var_filesystem_save_save, var_r

			; main.bas 26: Print "  Save gave"; r
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_53, glyph_61, glyph_76, glyph_65, glyph_20, glyph_67
			dw glyph_61, glyph_76, glyph_65, 0		; "  Save gave"
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 27: Wait
			dw p_wait_c

			; main.bas 28: Print "6 Load STEP.DAT..."
			dw kw_printzoscii
			dw glyph_36, glyph_20, glyph_4C, glyph_6F, glyph_61, glyph_64, glyph_20, glyph_53
			dw glyph_54, glyph_45, glyph_50, glyph_2E, glyph_44, glyph_41, glyph_54, glyph_2E
			dw glyph_2E, glyph_2E, 1, 0		; "6 Load STEP.DAT...\n"

			; main.bas 29: Wait
			dw p_wait_c

			; main.bas 30: r = FileSystem.Load("STEP.DAT", VarPtr(b), 20)
			dw fn_filesystem_load, str2, vp_arr_b, lit_20, var_r

			; main.bas 31: Print "  Load gave"; r; ", "; b(0); " ... "; b(9)
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_4C, glyph_6F, glyph_61, glyph_64, glyph_20, glyph_67
			dw glyph_61, glyph_76, glyph_65, 0		; "  Load gave"
			dw kw_printint, var_r
			dw kw_printzoscii
			dw glyph_2C, glyph_20, 0		; ", "
			dw kw_printint, arr_b
			dw kw_printzoscii
			dw glyph_20, glyph_2E, glyph_2E, glyph_2E, glyph_20, 0		; " ... "
			dw kw_printint, arr_b+18
			dw kw_printnl

			; main.bas 32: Print "7 done"
			dw kw_printzoscii
			dw glyph_37, glyph_20, glyph_64, glyph_6F, glyph_6E, glyph_65, 1, 0		; "7 done\n"

			; main.bas 33: End
			dw kw_printnl0
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, glyph_20, glyph_74, glyph_6F, glyph_20, glyph_65
			dw glyph_6E, glyph_64, 0		; "Press a key to end"
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub wait (normal mode)
; ============================================================

p_wait:

			; main.bas 36: Print "  (press a key)"
			dw kw_printzoscii
			dw glyph_20, glyph_20, glyph_28, glyph_70, glyph_72, glyph_65, glyph_73, glyph_73
			dw glyph_20, glyph_61, glyph_20, glyph_6B, glyph_65, glyph_79, glyph_29, 1
			dw 0		; "  (press a key)\n"

			; main.bas 37: Do While Inkey <> 0 : Loop
do2_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_e
			dw do2_t_go
do2_e:

			; main.bas 38: Do : Frame : Loop Until Inkey <> 0
do3_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do3_t
do3_e:
			dw p_wait_r

; ============================================================
; function save (normal mode)
; ============================================================

p_filesystem_save:

			; FileSystem.cls 82: Save = NotSupported
			dw kw_ltov, -1, var_filesystem_save_save
			dw p_filesystem_save_r

; ============================================================
; function devices (normal mode)
; ============================================================

p_filesystem_devices:

			; FileSystem.cls 239: If SelectVolume("R") = OK Then Devices = "ROM" Else Devices = ""
			dw p_filesystem_selectvolume_c, str3
			dw kw_vtov, var_filesystem_selectvolume_selectvolume, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse_n, if4_1
			dw kw_strcpy, var_filesystem_devices_devices, str4
			dw if4_e_go
if4_1:
			dw kw_strcpy, var_filesystem_devices_devices, str5
if4_e:
			dw p_filesystem_devices_r

; ============================================================
; function currentdevice (normal mode)
; ============================================================

p_filesystem_currentdevice:

			; FileSystem.cls 243: CurrentDevice = "ROM"
			dw kw_strcpy, var_filesystem_currentdevice_currentdevice, str4
			dw p_filesystem_currentdevice_r

; ============================================================
; function currentvolume (normal mode)
; ============================================================

p_filesystem_currentvolume:

			; FileSystem.cls 257: CurrentVolume = "R"
			dw kw_strcpy, var_filesystem_currentvolume_currentvolume, str3
			dw p_filesystem_currentvolume_r

; ============================================================
; function selectvolume (normal mode)
; ============================================================

p_filesystem_selectvolume:

			; FileSystem.cls 262: Dim v As String

			; FileSystem.cls 263: v = UCase$(name)
			dw kw_strucase, var_filesystem_selectvolume_v, var_filesystem_selectvolume_name

			; FileSystem.cls 264: If v = "R" Or v = "R:" Then
			dw kw_strcmpeq, var_filesystem_selectvolume_v, str3
			dw kw_ftov, tmp0
			dw kw_strcmpeq, var_filesystem_selectvolume_v, str6
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if7_1

			; FileSystem.cls 265: SelectVolume = SelVol()
			dw fn_filesystem_selvol, var_filesystem_selectvolume_selectvolume

			; FileSystem.cls 266: Else
			dw if7_e_go
if7_1:

			; FileSystem.cls 267: SelectVolume = NotFound
			dw kw_ltov, -2, var_filesystem_selectvolume_selectvolume

			; FileSystem.cls 268: End If
if7_e:
			dw p_filesystem_selectvolume_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_t_go:			ld sp, do2_t
			jp ntc_xn
if4_e_go:			ld sp, if4_e
			jp ntc_xn
if7_e_go:			ld sp, if7_e
			jp ntc_xn

p_wait_c:		; call wait (normal)
			ld (p_wait_rs), sp
			ld sp, p_wait
			jp ntc_xn
p_wait_r:		; end of wait
			ld sp, (p_wait_rs)
			jp ntc_xn
p_filesystem_save_c:		; call save (normal)
			pop hl			; name
			ld de, var_filesystem_save_name
			ld b, 40
p_filesystem_save_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_filesystem_save_si0_e
			inc hl
			inc de
			djnz p_filesystem_save_si0
			xor a
			ld (de), a
p_filesystem_save_si0_e:
			pop hl			; addr
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_filesystem_save_addr), de
			pop hl			; length
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_filesystem_save_length), de
			ld hl, 0
			ld (var_filesystem_save_save), hl
			ld (p_filesystem_save_rs), sp
			ld sp, p_filesystem_save
			jp ntc_xn
p_filesystem_save_r:		; end of save
			ld sp, (p_filesystem_save_rs)
			jp ntc_xn
p_filesystem_devices_c:		; call devices (normal)
			xor a
			ld (var_filesystem_devices_devices), a
			ld (p_filesystem_devices_rs), sp
			ld sp, p_filesystem_devices
			jp ntc_xn
p_filesystem_devices_r:		; end of devices
			ld sp, (p_filesystem_devices_rs)
			jp ntc_xn
p_filesystem_currentdevice_c:		; call currentdevice (normal)
			xor a
			ld (var_filesystem_currentdevice_currentdevice), a
			ld (p_filesystem_currentdevice_rs), sp
			ld sp, p_filesystem_currentdevice
			jp ntc_xn
p_filesystem_currentdevice_r:		; end of currentdevice
			ld sp, (p_filesystem_currentdevice_rs)
			jp ntc_xn
p_filesystem_currentvolume_c:		; call currentvolume (normal)
			xor a
			ld (var_filesystem_currentvolume_currentvolume), a
			ld (p_filesystem_currentvolume_rs), sp
			ld sp, p_filesystem_currentvolume
			jp ntc_xn
p_filesystem_currentvolume_r:		; end of currentvolume
			ld sp, (p_filesystem_currentvolume_rs)
			jp ntc_xn
p_filesystem_selectvolume_c:		; call selectvolume (normal)
			pop hl			; name
			ld de, var_filesystem_selectvolume_name
			ld b, 40
p_filesystem_selectvolume_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_filesystem_selectvolume_si0_e
			inc hl
			inc de
			djnz p_filesystem_selectvolume_si0
			xor a
			ld (de), a
p_filesystem_selectvolume_si0_e:
			ld hl, 0
			ld (var_filesystem_selectvolume_selectvolume), hl
			xor a
			ld (var_filesystem_selectvolume_v), a
			ld (p_filesystem_selectvolume_rs), sp
			ld sp, p_filesystem_selectvolume
			jp ntc_xn
p_filesystem_selectvolume_r:		; end of selectvolume
			ld sp, (p_filesystem_selectvolume_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_filesystem_capability:		; function capability (asm keyword), FileSystem.cls line 33
            pop hl		; FileSystem.cls 34
            pop de		; FileSystem.cls 35
            ld bc, fn_filesystem_capability_caps		; FileSystem.cls 36
            jp ntc_capfind		; FileSystem.cls 37
fn_filesystem_capability_caps:       db "LOAD", 0		; FileSystem.cls 38
            dw -1		; FileSystem.cls 39
            db "SEQUENTIAL", 0		; FileSystem.cls 40
            dw -1		; FileSystem.cls 41
            db "EXISTS", 0		; FileSystem.cls 42
            dw -1		; FileSystem.cls 43
            db "SIZE", 0		; FileSystem.cls 44
            dw -1		; FileSystem.cls 45
            db "DEVICES", 0		; FileSystem.cls 46
            dw -1		; FileSystem.cls 47
            db "VOLUMES", 0		; FileSystem.cls 48
            dw -1		; FileSystem.cls 49
            db "ROMDISC", 0		; FileSystem.cls 50
            dw -1		; FileSystem.cls 51
            db "MAXOPEN", 0		; FileSystem.cls 52
            dw 1		; FileSystem.cls 53
            db 0		; FileSystem.cls 54
			ret			; end of #asm

fn_filesystem_load:		; function load (asm keyword), FileSystem.cls line 61
            pop hl		; FileSystem.cls 62
            ld (rd_a1), hl		; FileSystem.cls 63
            pop hl		; FileSystem.cls 64
            ld e, (hl)		; FileSystem.cls 65
            inc hl		; FileSystem.cls 66
            ld d, (hl)		; FileSystem.cls 67
            ld (rd_a2), de		; FileSystem.cls 68
            pop hl		; FileSystem.cls 69
            ld e, (hl)		; FileSystem.cls 70
            inc hl		; FileSystem.cls 71
            ld d, (hl)		; FileSystem.cls 72
            ld (rd_a3), de		; FileSystem.cls 73
            pop hl		; FileSystem.cls 74
            ld (rd_res), hl		; FileSystem.cls 75
            ld hl, rd_load		; FileSystem.cls 76
            jp rd_go		; FileSystem.cls 77
			ret			; end of #asm

fn_filesystem_selvol:		; function selvol (asm keyword), FileSystem.cls line 272
            pop hl		; FileSystem.cls 273
            ld (rd_res), hl		; FileSystem.cls 274
            ld hl, rd_selvol		; FileSystem.cls 275
            jp rd_go		; FileSystem.cls 276
			ret			; end of #asm


